* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: #1a0638;
  overflow: hidden;
  overscroll-behavior: none;
  font-family: 'Baloo 2', 'Segoe UI', system-ui, sans-serif;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  perspective: 1200px;
}

#bg3d {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
}

#game-root {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

#game-root canvas {
  outline: none;
  touch-action: none;
}

/* ---------- Loading screen ---------- */
#loading-screen {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: radial-gradient(ellipse at center, #3a1266 0%, #1a0638 70%);
  transition: opacity 0.6s ease, visibility 0.6s ease;
}

#loading-screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.candy-spinner {
  position: relative;
  width: 90px;
  height: 90px;
  transform-style: preserve-3d;
  animation: spin3d 2.4s linear infinite;
}

@keyframes spin3d {
  from { transform: rotateY(0deg) rotateX(15deg); }
  to { transform: rotateY(360deg) rotateX(15deg); }
}

.candy-face {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  box-shadow: inset -8px -8px 16px rgba(0,0,0,0.35), inset 8px 8px 16px rgba(255,255,255,0.25);
}

.candy-f1 { background: linear-gradient(135deg, #ff6ec7, #ff2d95); transform: translateZ(28px); }
.candy-f2 { background: linear-gradient(135deg, #6ee7ff, #2d9dff); transform: rotateY(120deg) translateZ(28px); }
.candy-f3 { background: linear-gradient(135deg, #ffe76e, #ffb42d); transform: rotateY(240deg) translateZ(28px); }

.loading-title {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: 3px;
  color: #fff;
  text-shadow: 0 2px 0 #ff2d95, 0 4px 12px rgba(255,45,149,0.6);
}

.loading-bar-track {
  width: 220px;
  height: 10px;
  border-radius: 6px;
  background: rgba(255,255,255,0.15);
  overflow: hidden;
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.4);
}

.loading-bar-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #ff6ec7, #ffe76e);
  transition: width 0.2s ease;
}

.loading-tip {
  color: rgba(255,255,255,0.7);
  font-size: 13px;
  letter-spacing: 0.5px;
}

/* ---------- Orientation lock ---------- */
#orientation-lock {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: none;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  color: #fff;
  background: #1a0638;
  font-size: 18px;
}

@media (max-aspect-ratio: 1/1) and (max-height: 420px) {
  #orientation-lock { display: flex; }
}

