    const cleared = [];
    const collected = {};

    for (const [key, color] of clearCells.entries()) {
      const [r, c] = key.split(',').map(Number);
      const tile = this.grid[r][c];
      cleared.push({ r, c, color, id: tile ? tile.id : null, special: tile ? tile.special : SPECIAL.NONE });
      if (color >= 0) collected[color] = (collected[color] || 0) + 1;
      this.grid[r][c] = null;
    }

    const specialsCreated = [];
    for (const spec of specialsToSpawn) {
      const tile = this._makeTile(spec.color, spec.type);
      this.grid[spec.r][spec.c] = tile;
      specialsCreated.push({ r: spec.r, c: spec.c, type: spec.type, color: spec.color, id: tile.id });
    }

    const { fallMoves: rawFallMoves, spawns } = this._applyGravityAndRefill();
    const fallMoves = rawFallMoves.map((m) => ({ ...m, fromRow: positionsBefore.get(m.id) ?? m.fromRow }));

    let score = 0;
    score += cleared.length * 60 * comboIndex;
    score += specialsCreated.length * 150;
    score += activatedSpecials.length * 300;

    return { cleared, specialsCreated, activatedSpecials, fallMoves, spawns, comboIndex, score, collected };
  }

  hasAvailableMoves() {
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        const tile = this.grid[r][c];
        if (tile && tile.special !== SPECIAL.NONE) return true;
        if (c + 1 < this.cols) {
