import { COLORS, SPECIAL } from './constants.js';

let UID = 1;
const nextId = () => UID++;

function randColor(numColors) {
  return Math.floor(Math.random() * numColors);
}

export class Match3Board {
  constructor(rows, cols, numColors = 6) {
    this.rows = rows;
    this.cols = cols;
    this.numColors = Math.min(numColors, COLORS.length);
    this.grid = [];
    this._init();
  }

  _init() {
    for (let r = 0; r < this.rows; r++) {
      const row = [];
      for (let c = 0; c < this.cols; c++) {
        row.push(this._makeNonMatchingTile(r, c));
      }
      this.grid.push(row);
    }
    if (!this.hasAvailableMoves()) this.shuffleBoard();
  }

  _makeTile(color, special = SPECIAL.NONE) {
    return { id: nextId(), color, special };
  }

  _makeNonMatchingTile(r, c) {
    let color;
    let tries = 0;
    do {
      color = randColor(this.numColors);
      tries++;
    } while (tries < 20 && this._wouldFormMatchAt(r, c, color));
    return this._makeTile(color);
  }

  _wouldFormMatchAt(r, c, color) {
    if (c >= 2) {
      const a = this.grid[r]?.[c - 1];
      const b = this.grid[r]?.[c - 2];
      if (a && b && a.color === color && b.color === color) return true;
    }
    if (r >= 2) {
      const a = this.grid[r - 1]?.[c];
      const b = this.grid[r - 2]?.[c];
      if (a && b && a.color === color && b.color === color) return true;
    }
    return false;
  }

  tileAt(r, c) {
    if (r < 0 || r >= this.rows || c < 0 || c >= this.cols) return null;
    return this.grid[r][c];
  }

  isAdjacent(ar, ac, br, bc) {
    const dr = Math.abs(ar - br);
    const dc = Math.abs(ac - bc);
    return (dr === 1 && dc === 0) || (dr === 0 && dc === 1);
  }

  // ---------- run / shape detection ----------

  _findRuns() {
    const hRunOfCell = Array.from({ length: this.rows }, () => new Array(this.cols).fill(null));
    const vRunOfCell = Array.from({ length: this.rows }, () => new Array(this.cols).fill(null));
    const runs = [];

    for (let r = 0; r < this.rows; r++) {
      let c = 0;
      while (c < this.cols) {
        const tile = this.grid[r][c];
        if (!tile || tile.special === SPECIAL.BOMB) { c++; continue; }
        let end = c;
        while (end + 1 < this.cols) {
          const t2 = this.grid[r][end + 1];
          if (t2 && t2.special !== SPECIAL.BOMB && t2.color === tile.color) end++;
          else break;
        }
        const len = end - c + 1;
        if (len >= 3) {
          const run = { orientation: 'h', row: r, colStart: c, colEnd: end, color: tile.color, len };
          runs.push(run);
          for (let cc = c; cc <= end; cc++) hRunOfCell[r][cc] = run;
        }
        c = end + 1;
      }
    }

    for (let c = 0; c < this.cols; c++) {
      let r = 0;
      while (r < this.rows) {
        const tile = this.grid[r][c];
        if (!tile || tile.special === SPECIAL.BOMB) { r++; continue; }
        let end = r;
        while (end + 1 < this.rows) {
          const t2 = this.grid[end + 1][c];
          if (t2 && t2.special !== SPECIAL.BOMB && t2.color === tile.color) end++;
          else break;
        }
        const len = end - r + 1;
        if (len >= 3) {
          const run = { orientation: 'v', col: c, rowStart: r, rowEnd: end, color: tile.color, len };
          runs.push(run);
          for (let rr = r; rr <= end; rr++) vRunOfCell[rr][c] = run;
        }
        r = end + 1;
      }
    }

    return { runs, hRunOfCell, vRunOfCell };
  }

  _matchedCellSetFromRuns(runs) {
    const set = new Map(); // key "r,c" -> true
    for (const run of runs) {
      if (run.orientation === 'h') {
        for (let c = run.colStart; c <= run.colEnd; c++) set.set(`${run.row},${c}`, true);
      } else {
        for (let r = run.rowStart; r <= run.rowEnd; r++) set.set(`${r},${run.col}`, true);
      }
    }
    return set;
  }

  /**
   * Analyse the current grid for matches, group into connected shapes,
   * and decide what special candies (if any) should spawn.
   * swapHint: optional {ar,ac,br,bc} - prefer spawning specials at the swapped cell.
   */
  _analyse(swapHint) {
    const { runs, hRunOfCell, vRunOfCell } = this._findRuns();
    if (runs.length === 0) return null;

    const matchedSet = this._matchedCellSetFromRuns(runs);
    if (matchedSet.size === 0) return null;

    const visited = new Set();
    const components = [];
    for (const key of matchedSet.keys()) {
      if (visited.has(key)) continue;
      const [r0, c0] = key.split(',').map(Number);
      const stack = [[r0, c0]];
      visited.add(key);
      const cells = [];
      while (stack.length) {
        const [r, c] = stack.pop();
        cells.push([r, c]);
        const neighbours = [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]];
        for (const [nr, nc] of neighbours) {
          const nk = `${nr},${nc}`;
          if (matchedSet.has(nk) && !visited.has(nk)) {
            visited.add(nk);
            stack.push([nr, nc]);
          }
        }
      }
      components.push(cells);
    }

    const clearCells = new Map(); // "r,c" -> color
    const specialsToSpawn = []; // {r,c,type,color}

    const hintMatches = (r, c) => swapHint && (
      (r === swapHint.ar && c === swapHint.ac) || (r === swapHint.br && c === swapHint.bc)
    );

    for (const cells of components) {
      for (const [r, c] of cells) clearCells.set(`${r},${c}`, this.grid[r][c].color);

      const bigRun = cells
        .map(([r, c]) => hRunOfCell[r][c] || vRunOfCell[r][c])
        .find((run) => run && run.len >= 5);

      let crossCell = null;
      for (const [r, c] of cells) {
        if (hRunOfCell[r][c] && hRunOfCell[r][c].len >= 3 && vRunOfCell[r][c] && vRunOfCell[r][c].len >= 3) {
          if (!crossCell || hintMatches(r, c)) crossCell = [r, c];
        }
      }

      const fourRun = cells
        .map(([r, c]) => hRunOfCell[r][c] || vRunOfCell[r][c])
        .find((run) => run && run.len === 4);

      if (bigRun) {
        let spawnCell = cells.find(([r, c]) => hintMatches(r, c));
        if (!spawnCell) {
          spawnCell = bigRun.orientation === 'h'
            ? [bigRun.row, Math.floor((bigRun.colStart + bigRun.colEnd) / 2)]
            : [Math.floor((bigRun.rowStart + bigRun.rowEnd) / 2), bigRun.col];
        }
        specialsToSpawn.push({ r: spawnCell[0], c: spawnCell[1], type: SPECIAL.BOMB, color: bigRun.color });
      } else if (crossCell) {
        specialsToSpawn.push({ r: crossCell[0], c: crossCell[1], type: SPECIAL.WRAPPED, color: this.grid[crossCell[0]][crossCell[1]].color });
      } else if (fourRun) {
        let spawnCell = cells.find(([r, c]) => hintMatches(r, c));
        if (!spawnCell) {
          spawnCell = fourRun.orientation === 'h'
            ? [fourRun.row, Math.floor((fourRun.colStart + fourRun.colEnd) / 2)]
            : [Math.floor((fourRun.rowStart + fourRun.rowEnd) / 2), fourRun.col];
        }
        const type = fourRun.orientation === 'h' ? SPECIAL.STRIPED_ROW : SPECIAL.STRIPED_COL;
        specialsToSpawn.push({ r: spawnCell[0], c: spawnCell[1], type, color: fourRun.color });
      }
    }

    return { clearCells, specialsToSpawn };
  }

  // ---------- special activation ----------

  _activationCells(r, c, tile) {
    const cells = new Set();
    cells.add(`${r},${c}`);
    if (tile.special === SPECIAL.STRIPED_ROW) {
      for (let cc = 0; cc < this.cols; cc++) cells.add(`${r},${cc}`);
    } else if (tile.special === SPECIAL.STRIPED_COL) {
      for (let rr = 0; rr < this.rows; rr++) cells.add(`${rr},${c}`);
    } else if (tile.special === SPECIAL.WRAPPED) {
      for (let rr = r - 1; rr <= r + 1; rr++) {
        for (let cc = c - 1; cc <= c + 1; cc++) {
          if (rr >= 0 && rr < this.rows && cc >= 0 && cc < this.cols) cells.add(`${rr},${cc}`);
        }
      }
    } else if (tile.special === SPECIAL.BOMB) {
      for (let rr = 0; rr < this.rows; rr++) {
        for (let cc = 0; cc < this.cols; cc++) {
          if (this.grid[rr][cc] && this.grid[rr][cc].color === tile.color) cells.add(`${rr},${cc}`);
        }
      }
    }
    return cells;
  }

  _expandWithSpecials(clearCells) {
    const activated = [];
    const queue = Array.from(clearCells.keys());
    const seen = new Set(queue);
    while (queue.length) {
      const key = queue.pop();
      const [r, c] = key.split(',').map(Number);
      const tile = this.grid[r]?.[c];
      if (!tile || tile.special === SPECIAL.NONE) continue;
      activated.push({ r, c, special: tile.special, color: tile.color });
      const extra = this._activationCells(r, c, tile);
      for (const ek of extra) {
        if (!seen.has(ek)) {
          seen.add(ek);
          queue.push(ek);
          const [er, ec] = ek.split(',').map(Number);
          const et = this.grid[er]?.[ec];
          if (et) clearCells.set(ek, et.color);
        }
      }
    }
    return activated;
  }

  // ---------- gravity ----------

  _applyGravityAndRefill() {
    const fallMoves = [];
    const spawns = [];
    for (let c = 0; c < this.cols; c++) {
      const remaining = [];
      for (let r = this.rows - 1; r >= 0; r--) {
        if (this.grid[r][c]) remaining.push(this.grid[r][c]);
      }
      let writeRow = this.rows - 1;
      for (const tile of remaining) {
        const oldRow = this._findRowOfTileInColumn(c, tile.id) ?? writeRow;
        if (writeRow !== oldRow) fallMoves.push({ id: tile.id, fromRow: oldRow, toRow: writeRow, col: c });
        this.grid[writeRow][c] = tile;
        writeRow--;
      }
      let spawnOffset = 1;
      for (let r = writeRow; r >= 0; r--) {
        const tile = this._makeTile(randColor(this.numColors));
        this.grid[r][c] = tile;
        spawns.push({ id: tile.id, col: c, toRow: r, fromOffset: spawnOffset, color: tile.color });
        spawnOffset++;
      }
    }
    return { fallMoves, spawns };
  }

  _findRowOfTileInColumn(c, id) {
    for (let r = 0; r < this.rows; r++) {
      if (this.grid[r][c] && this.grid[r][c].id === id) return r;
    }
    return null;
  }

  // Snapshot the pre-gravity grid so fallMoves 'fromRow' can be computed correctly
  // (we mutate grid progressively, so capture positions before clearing).
  _snapshotPositions() {
    const pos = new Map();
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        const t = this.grid[r][c];
        if (t) pos.set(t.id, r);
      }
    }
    return pos;
  }

  // ---------- public turn resolution ----------

  trySwap(ar, ac, br, bc) {
    if (!this.isAdjacent(ar, ac, br, bc)) return { invalid: true };
    const tileA = this.tileAt(ar, ac);
    const tileB = this.tileAt(br, bc);
    if (!tileA || !tileB) return { invalid: true };

    this.grid[ar][ac] = tileB;
    this.grid[br][bc] = tileA;

    const waves = [];
    let scoreGained = 0;
    const collected = {};

    const addCollected = (color, n) => {
      if (color < 0) return;
      collected[color] = (collected[color] || 0) + n;
    };

    const bombInvolved = tileA.special === SPECIAL.BOMB || tileB.special === SPECIAL.BOMB;
    const bothSpecial = tileA.special !== SPECIAL.NONE && tileB.special !== SPECIAL.NONE;

    if (bombInvolved || bothSpecial) {
      const manualClear = new Map();
      if (tileA.special === SPECIAL.BOMB && tileB.special === SPECIAL.BOMB) {
        for (let r = 0; r < this.rows; r++) for (let c = 0; c < this.cols; c++) {
          if (this.grid[r][c]) manualClear.set(`${r},${c}`, this.grid[r][c].color);
        }
      } else if (tileA.special === SPECIAL.BOMB || tileB.special === SPECIAL.BOMB) {
        const bomb = tileA.special === SPECIAL.BOMB ? tileA : tileB;
        const other = tileA.special === SPECIAL.BOMB ? tileB : tileA;
        for (let r = 0; r < this.rows; r++) {
          for (let c = 0; c < this.cols; c++) {
            const t = this.grid[r][c];
            if (!t) continue;
            if (t.color === other.color) {
              const upgraded = other.special !== SPECIAL.NONE ? other.special : SPECIAL.STRIPED_ROW;
              this.grid[r][c] = this._makeTile(t.color, upgraded);
              manualClear.set(`${r},${c}`, t.color);
            }
          }
        }
        manualClear.set(`${ar},${ac}`, tileA.color);
        manualClear.set(`${br},${bc}`, tileB.color);
      } else {
        const cellsA = this._activationCells(ar, ac, tileB.special !== SPECIAL.NONE ? tileB : tileA);
        const cellsB = this._activationCells(br, bc, tileA.special !== SPECIAL.NONE ? tileA : tileB);
        for (const k of cellsA) manualClear.set(k, this.grid[k.split(',').map(Number)[0]][k.split(',').map(Number)[1]]?.color ?? -1);
        for (const k of cellsB) manualClear.set(k, this.grid[k.split(',').map(Number)[0]][k.split(',').map(Number)[1]]?.color ?? -1);
      }

      const activated = this._expandWithSpecials(manualClear);
      const wave = this._commitWave(manualClear, [], activated, 1);
      waves.push(wave);
      scoreGained += wave.score;
      for (const [color, n] of Object.entries(wave.collected)) addCollected(Number(color), n);
    } else {
      const analysis = this._analyse({ ar, ac, br, bc });
      if (!analysis) {
        this.grid[ar][ac] = tileA;
        this.grid[br][bc] = tileB;
        return { invalid: true };
      }
    }

    // generic cascade loop
    let comboIndex = waves.length;
    let swapHintUsed = waves.length > 0;
    for (;;) {
      const analysis = this._analyse();
      if (!analysis) break;
      comboIndex++;
      for (const spec of analysis.specialsToSpawn) analysis.clearCells.delete(`${spec.r},${spec.c}`);
      const activated = this._expandWithSpecials(analysis.clearCells);
      const wave = this._commitWave(analysis.clearCells, analysis.specialsToSpawn, activated, comboIndex);
      waves.push(wave);
      scoreGained += wave.score;
      for (const [color, n] of Object.entries(wave.collected)) addCollected(Number(color), n);
    }

    return { invalid: false, waves, scoreGained, collected };
  }

  _commitWave(clearCells, specialsToSpawn, activatedSpecials, comboIndex) {
    const positionsBefore = this._snapshotPositions();
    const cleared = [];
    const collected = {};

    for (const [key, color] of clearCells.entries()) {
      const [r, c] = key.split(',').map(Number);
      const tile = this.grid[r][c];
      cleared.push({ r, c, color, id: tile ? tile.id : null, special: tile ? tile.special : SPECIAL.NONE });
      if (color >= 0) collected[color] = (collected[color] || 0) + 1;
      this.grid[r][c] = null;
    }

    const specialsCreated = [];
    for (const spec of specialsToSpawn) {
      const tile = this._makeTile(spec.color, spec.type);
