        if (r + 1 < this.rows) {
          this._swapCells(r, c, r + 1, c);
          const found = this._analyse({ ar: r, ac: c, br: r + 1, bc: c }) !== null;
          this._swapCells(r, c, r + 1, c);
          if (found) return true;
        }
      }
    }
    return false;
  }

  _swapCells(ar, ac, br, bc) {
    const tmp = this.grid[ar][ac];
    this.grid[ar][ac] = this.grid[br][bc];
    this.grid[br][bc] = tmp;
  }

  shuffleBoard() {
    let attempts = 0;
    do {
      const flat = [];
      for (let r = 0; r < this.rows; r++) for (let c = 0; c < this.cols; c++) flat.push(this.grid[r][c]);
