import { COLORS, SPECIAL } from '../game/constants.js';

const PALETTE = {
  red: { base: '#ff5577', light: '#ffc2d1', dark: '#b4123f' },
  orange: { base: '#ff9a3c', light: '#ffe0b2', dark: '#c65a00' },
  yellow: { base: '#ffd93c', light: '#fff6c2', dark: '#c99a00' },
  green: { base: '#4ee08a', light: '#c6ffe1', dark: '#0f8f4c' },
  blue: { base: '#3cb4ff', light: '#c6ebff', dark: '#0063a8' },
  purple: { base: '#b76bff', light: '#e9d1ff', dark: '#6c1fb0' }
};

function mkCanvas(size) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  return canvas;
}

function withShadow(ctx, size, draw) {
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.35)';
  ctx.shadowBlur = size * 0.08;
  ctx.shadowOffsetY = size * 0.05;
  draw();
  ctx.restore();
}

function glossHighlight(ctx, size, cx, cy, r) {
  const g = ctx.createRadialGradient(cx - r * 0.35, cy - r * 0.45, r * 0.05, cx - r * 0.1, cy - r * 0.1, r * 1.1);
  g.addColorStop(0, 'rgba(255,255,255,0.85)');
  g.addColorStop(0.5, 'rgba(255,255,255,0.15)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
}

// --- base candy shapes, one distinct silhouette per color so shape + color both read the type ---

function drawGumdrop(ctx, size, pal) {
  const cx = size / 2, cy = size / 2, r = size * 0.36;
  withShadow(ctx, size, () => {
    const g = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.55, pal.base);
    g.addColorStop(1, pal.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
  });
  glossHighlight(ctx, size, cx, cy, r);
}

function drawSwirl(ctx, size, pal) {
  const cx = size / 2, cy = size / 2, r = size * 0.36;
  withShadow(ctx, size, () => {
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = pal.light;
    ctx.fillRect(0, 0, size, size);
    ctx.strokeStyle = pal.base;
    ctx.lineWidth = r * 0.3;
    for (let i = -2; i < 4; i++) {
      ctx.beginPath();
      ctx.arc(cx + i * r * 0.5, cy + i * r * 0.5, r * 1.3, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
    ctx.strokeStyle = pal.dark;
    ctx.lineWidth = size * 0.02;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
  });
  glossHighlight(ctx, size, cx, cy, r);
}

function drawStar(ctx, size, pal) {
  const cx = size / 2, cy = size / 2, rOuter = size * 0.4, rInner = size * 0.18;
  withShadow(ctx, size, () => {
    const g = ctx.createRadialGradient(cx, cy, rInner * 0.2, cx, cy, rOuter);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.6, pal.base);
    g.addColorStop(1, pal.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const ang = (Math.PI / 5) * i - Math.PI / 2;
      const rad = i % 2 === 0 ? rOuter : rInner;
      const x = cx + Math.cos(ang) * rad;
      const y = cy + Math.sin(ang) * rad;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
  });
  glossHighlight(ctx, size, cx, cy - size * 0.05, rOuter * 0.6);
}

function roundedRectPath(ctx, x, y, w, h, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function drawSquare(ctx, size, pal) {
  const pad = size * 0.16;
  const w = size - pad * 2;
  withShadow(ctx, size, () => {
    const g = ctx.createLinearGradient(pad, pad, pad, pad + w);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.5, pal.base);
    g.addColorStop(1, pal.dark);
    roundedRectPath(ctx, pad, pad, w, w, size * 0.14);
    ctx.fillStyle = g;
    ctx.fill();
  });
  glossHighlight(ctx, size, size / 2, size * 0.4, w * 0.4);
}

function drawDiamond(ctx, size, pal) {
  const cx = size / 2, cy = size / 2, r = size * 0.38;
  withShadow(ctx, size, () => {
    const g = ctx.createLinearGradient(cx, cy - r, cx, cy + r);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.5, pal.base);
