    ctx.fillRect(0, 0, size, size);
    ctx.strokeStyle = pal.base;
    ctx.lineWidth = r * 0.3;
    for (let i = -2; i < 4; i++) {
      ctx.beginPath();
      ctx.arc(cx + i * r * 0.5, cy + i * r * 0.5, r * 1.3, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
    ctx.strokeStyle = pal.dark;
    ctx.lineWidth = size * 0.02;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
  });
  glossHighlight(ctx, size, cx, cy, r);
}

function drawStar(ctx, size, pal) {
  const cx = size / 2, cy = size / 2, rOuter = size * 0.4, rInner = size * 0.18;
  withShadow(ctx, size, () => {
    const g = ctx.createRadialGradient(cx, cy, rInner * 0.2, cx, cy, rOuter);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.6, pal.base);
    g.addColorStop(1, pal.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const ang = (Math.PI / 5) * i - Math.PI / 2;
      const rad = i % 2 === 0 ? rOuter : rInner;
      const x = cx + Math.cos(ang) * rad;
      const y = cy + Math.sin(ang) * rad;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
  });
  glossHighlight(ctx, size, cx, cy - size * 0.05, rOuter * 0.6);
}

function roundedRectPath(ctx, x, y, w, h, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function drawSquare(ctx, size, pal) {
  const pad = size * 0.16;
  const w = size - pad * 2;
  withShadow(ctx, size, () => {
    const g = ctx.createLinearGradient(pad, pad, pad, pad + w);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.5, pal.base);
    g.addColorStop(1, pal.dark);
    roundedRectPath(ctx, pad, pad, w, w, size * 0.14);
    ctx.fillStyle = g;
    ctx.fill();
  });
  glossHighlight(ctx, size, size / 2, size * 0.4, w * 0.4);
}

function drawDiamond(ctx, size, pal) {
  const cx = size / 2, cy = size / 2, r = size * 0.38;
  withShadow(ctx, size, () => {
    const g = ctx.createLinearGradient(cx, cy - r, cx, cy + r);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.5, pal.base);
    g.addColorStop(1, pal.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(cx, cy - r);
    ctx.lineTo(cx + r * 0.78, cy - r * 0.15);
    ctx.lineTo(cx, cy + r);
    ctx.lineTo(cx - r * 0.78, cy - r * 0.15);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.5)';
    ctx.lineWidth = size * 0.012;
    ctx.beginPath();
    ctx.moveTo(cx, cy - r);
    ctx.lineTo(cx, cy + r);
    ctx.stroke();
  });
  glossHighlight(ctx, size, cx - r * 0.2, cy - r * 0.3, r * 0.4);
}

function drawJellyBean(ctx, size, pal) {
  const cx = size / 2, cy = size / 2;
  const w = size * 0.3, h = size * 0.42;
  withShadow(ctx, size, () => {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(-0.4);
    const g = ctx.createLinearGradient(-w, -h, w, h);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.5, pal.base);
    g.addColorStop(1, pal.dark);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, w, h, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  });
  glossHighlight(ctx, size, cx - w * 0.3, cy - h * 0.4, w * 0.6);
}

const SHAPE_DRAWERS = [drawGumdrop, drawSwirl, drawStar, drawSquare, drawDiamond, drawJellyBean];

function drawStripesOverlay(ctx, size, orientation) {
  ctx.save();
  const cx = size / 2, cy = size / 2, r = size * 0.36;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.clip();
  ctx.fillStyle = 'rgba(255,255,255,0.0)';
  ctx.fillRect(0, 0, size, size);
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.lineWidth = size * 0.07;
  const count = 5;
  for (let i = -count; i <= count; i++) {
    ctx.beginPath();
    if (orientation === 'h') {
      const y = cy + i * size * 0.09;
      ctx.moveTo(cx - r * 1.2, y);
      ctx.lineTo(cx + r * 1.2, y);
    } else {
      const x = cx + i * size * 0.09;
      ctx.moveTo(x, cy - r * 1.2);
      ctx.lineTo(x, cy + r * 1.2);
    }
    ctx.stroke();
  }
  ctx.restore();
  ctx.strokeStyle = 'rgba(255,255,255,0.9)';
  ctx.lineWidth = size * 0.025;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.stroke();
}

function drawWrappedOverlay(ctx, size) {
  const cx = size / 2, cy = size / 2;
  ctx.save();
  ctx.globalAlpha = 0.95;
  const metal = ctx.createLinearGradient(0, 0, size, size);
  metal.addColorStop(0, '#f4f7ff');
  metal.addColorStop(0.5, '#c7d3e8');
  metal.addColorStop(1, '#8fa0c2');
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.translate(cx + side * size * 0.33, cy);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(side * size * 0.22, -size * 0.14);
    ctx.lineTo(side * size * 0.3, 0);
    ctx.lineTo(side * size * 0.22, size * 0.14);
    ctx.closePath();
    ctx.fillStyle = metal;
    ctx.fill();
    ctx.strokeStyle = 'rgba(100,110,140,0.6)';
    ctx.lineWidth = size * 0.01;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}

function drawBomb(ctx, size) {
  const cx = size / 2, cy = size / 2, r = size * 0.38;
  withShadow(ctx, size, () => {
    const hue = (Date.now() / 20) % 360;
    const g = ctx.createRadialGradient(cx, cy, r * 0.05, cx, cy, r);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.25, '#ffe0fb');
    g.addColorStop(0.55, '#c285ff');
    g.addColorStop(0.8, '#6a2bd9');
    g.addColorStop(1, '#2a0a63');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.save();
  ctx.strokeStyle = 'rgba(255,255,255,0.65)';
  ctx.lineWidth = size * 0.018;
  for (let i = 0; i < 8; i++) {
    const ang = (Math.PI / 4) * i;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(ang) * r * 0.55, cy + Math.sin(ang) * r * 0.55);
    ctx.lineTo(cx + Math.cos(ang) * r * 1.05, cy + Math.sin(ang) * r * 1.05);
    ctx.stroke();
  }
  ctx.restore();
  glossHighlight(ctx, size, cx - r * 0.3, cy - r * 0.35, r * 0.5);
}

export function generateCandyTextures(scene, size = 128) {
  const keys = [];

  COLORS.forEach((name, idx) => {
    const pal = PALETTE[name];
    const draw = SHAPE_DRAWERS[idx % SHAPE_DRAWERS.length];

    const baseCanvas = mkCanvas(size);
    draw(baseCanvas.getContext('2d'), size, pal);
    scene.textures.addCanvas(`candy_${idx}`, baseCanvas);
    keys.push(`candy_${idx}`);

    for (const [suffix, orientation] of [['striped_h', 'h'], ['striped_v', 'v']]) {
      const c = mkCanvas(size);
      const ctx = c.getContext('2d');
      draw(ctx, size, pal);
      drawStripesOverlay(ctx, size, orientation);
      scene.textures.addCanvas(`candy_${idx}_${suffix}`, c);
      keys.push(`candy_${idx}_${suffix}`);
    }

    const wrapped = mkCanvas(size);
    const wctx = wrapped.getContext('2d');
    draw(wctx, size, pal);
    drawWrappedOverlay(wctx, size);
    scene.textures.addCanvas(`candy_${idx}_wrapped`, wrapped);
    keys.push(`candy_${idx}_wrapped`);
  });

  const bombCanvas = mkCanvas(size);
  drawBomb(bombCanvas.getContext('2d'), size);
  scene.textures.addCanvas('candy_bomb', bombCanvas);
  keys.push('candy_bomb');

  // soft round particle
  const glow = mkCanvas(64);
  const gctx = glow.getContext('2d');
  const gg = gctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  gg.addColorStop(0, 'rgba(255,255,255,1)');
  gg.addColorStop(1, 'rgba(255,255,255,0)');
  gctx.fillStyle = gg;
  gctx.fillRect(0, 0, 64, 64);
  scene.textures.addCanvas('particle_glow', glow);

  // sparkle star particle
  const spark = mkCanvas(64);
  const sctx = spark.getContext('2d');
  sctx.translate(32, 32);
  sctx.fillStyle = '#ffffff';
  sctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const ang = (Math.PI / 4) * i;
    const rad = i % 2 === 0 ? 30 : 10;
    const x = Math.cos(ang) * rad, y = Math.sin(ang) * rad;
    if (i === 0) sctx.moveTo(x, y); else sctx.lineTo(x, y);
  }
  sctx.closePath();
  sctx.fill();
  scene.textures.addCanvas('particle_spark', spark);

  return keys;
}

export function textureKeyFor(color, special) {
  if (special === SPECIAL.BOMB) return 'candy_bomb';
  if (special === SPECIAL.STRIPED_ROW) return `candy_${color}_striped_h`;
  if (special === SPECIAL.STRIPED_COL) return `candy_${color}_striped_v`;
  if (special === SPECIAL.WRAPPED) return `candy_${color}_wrapped`;
  return `candy_${color}`;
}

export { PALETTE };

