const NOTE = {
  C3: 130.81, D3: 146.83, E3: 164.81, F3: 174.61, G3: 196.00, A3: 220.00, B3: 246.94,
  C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, G4: 392.00, A4: 440.00, B4: 493.88,
  C5: 523.25, D5: 587.33, E5: 659.25, F5: 698.46, G5: 783.99, A5: 880.00, B5: 987.77,
  C6: 1046.50, D6: 1174.66, E6: 1318.51
};

const CHORDS = [
  [NOTE.C4, NOTE.E4, NOTE.G4, NOTE.C5],
  [NOTE.A3, NOTE.C4, NOTE.E4, NOTE.A4],
  [NOTE.F3, NOTE.A3, NOTE.C4, NOTE.F4],
  [NOTE.G3, NOTE.B3, NOTE.D4, NOTE.G4]
];

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.musicMuted = false;
    this.sfxMuted = false;
    this._musicTimer = null;
    this._musicStep = 0;
    this._nextNoteTime = 0;
    this._started = false;
  }

  init() {
    if (this._started) return;
    this._started = true;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 1;
    this.master.connect(this.ctx.destination);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = this.musicMuted ? 0 : 0.35;
    this.musicGain.connect(this.master);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = this.sfxMuted ? 0 : 0.8;
    this.sfxGain.connect(this.master);
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
  }

  setMusicMuted(muted) {
    this.musicMuted = muted;
    if (this.musicGain) this.musicGain.gain.setTargetAtTime(muted ? 0 : 0.35, this.ctx.currentTime, 0.05);
  }

  setSfxMuted(muted) {
    this.sfxMuted = muted;
    if (this.sfxGain) this.sfxGain.gain.setTargetAtTime(muted ? 0 : 0.8, this.ctx.currentTime, 0.05);
  }

  // ---------------- low level helpers ----------------

  _tone({ freq, start, dur, type = 'sine', gain = 0.3, attack = 0.01, release = 0.08, detune = 0, dest }) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, start);
    if (detune) osc.detune.setValueAtTime(detune, start);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, start);
    g.gain.linearRampToValueAtTime(gain, start + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, start + dur + release);
    osc.connect(g);
    g.connect(dest || this.sfxGain);
    osc.start(start);
    osc.stop(start + dur + release + 0.05);
  }

  _noise({ start, dur, gain = 0.3, filterFreq = 2000, filterType = 'bandpass', dest }) {
    if (!this.ctx) return;
    const bufferSize = this.ctx.sampleRate * dur;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.value = filterFreq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, start);
    g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(dest || this.sfxGain);
    src.start(start);
    src.stop(start + dur + 0.05);
  }

  // ---------------- sfx ----------------

  swap() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this._tone({ freq: 420, start: t, dur: 0.07, type: 'sine', gain: 0.18 });
    this._tone({ freq: 620, start: t + 0.03, dur: 0.07, type: 'sine', gain: 0.14 });
  }

  invalidSwap() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this._tone({ freq: 180, start: t, dur: 0.12, type: 'square', gain: 0.1 });
  }

  pop(chainIndex = 1) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const base = 500 + Math.min(chainIndex, 8) * 70;
    this._tone({ freq: base, start: t, dur: 0.1, type: 'triangle', gain: 0.22 });
    this._tone({ freq: base * 1.5, start: t + 0.03, dur: 0.12, type: 'sine', gain: 0.16 });
  }

  specialCreate() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [0, 0.06, 0.12].forEach((d, i) => {
      this._tone({ freq: 700 + i * 160, start: t + d, dur: 0.1, type: 'sine', gain: 0.18 });
    });
  }

  specialActivate(kind = 'striped') {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    if (kind === 'bomb') {
      this._noise({ start: t, dur: 0.5, gain: 0.35, filterFreq: 1800, filterType: 'bandpass' });
      [NOTE.C5, NOTE.E5, NOTE.G5, NOTE.C6].forEach((f, i) => {
        this._tone({ freq: f, start: t + i * 0.05, dur: 0.18, type: 'sawtooth', gain: 0.16 });
      });
    } else if (kind === 'wrapped') {
      this._noise({ start: t, dur: 0.3, gain: 0.3, filterFreq: 1200 });
      this._tone({ freq: 300, start: t, dur: 0.2, type: 'sine', gain: 0.2 });
    } else {
      this._noise({ start: t, dur: 0.22, gain: 0.22, filterFreq: 3000 });
      this._tone({ freq: 900, start: t, dur: 0.15, type: 'triangle', gain: 0.15 });
    }
  }

  buttonClick() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this._tone({ freq: 760, start: t, dur: 0.04, type: 'square', gain: 0.12 });
  }

  levelWin() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [NOTE.C5, NOTE.E5, NOTE.G5, NOTE.C6].forEach((f, i) => {
      this._tone({ freq: f, start: t + i * 0.12, dur: 0.22, type: 'triangle', gain: 0.22 });
    });
  }

  levelLose() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [NOTE.A4, NOTE.F4, NOTE.D4, NOTE.C4].forEach((f, i) => {
      this._tone({ freq: f, start: t + i * 0.16, dur: 0.3, type: 'sawtooth', gain: 0.16 });
    });
  }

  star() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this._tone({ freq: NOTE.E5, start: t, dur: 0.12, type: 'sine', gain: 0.2 });
    this._tone({ freq: NOTE.C6, start: t + 0.08, dur: 0.18, type: 'sine', gain: 0.2 });
  }

  // ---------------- background music ----------------

  startMusic() {
    if (!this.ctx || this._musicTimer) return;
    this._musicStep = 0;
    this._nextNoteTime = this.ctx.currentTime + 0.1;
    const lookahead = 0.12;
    const scheduleAheadTime = 0.3;

    const scheduler = () => {
      while (this._nextNoteTime < this.ctx.currentTime + scheduleAheadTime) {
        this._scheduleMusicStep(this._musicStep, this._nextNoteTime);
        this._nextNoteTime += 0.42;
        this._musicStep++;
      }
    };
    scheduler();
    this._musicTimer = setInterval(scheduler, lookahead * 1000);
  }

  stopMusic() {
    if (this._musicTimer) {
      clearInterval(this._musicTimer);
      this._musicTimer = null;
    }
  }

  _scheduleMusicStep(step, time) {
    const chord = CHORDS[Math.floor(step / 8) % CHORDS.length];
    const noteInChord = chord[step % chord.length];

    this._tone({ freq: noteInChord / 2, start: time, dur: 0.38, type: 'sine', gain: 0.1, dest: this.musicGain });

    if (step % 2 === 0) {
      this._tone({ freq: noteInChord, start: time, dur: 0.3, type: 'triangle', gain: 0.07, dest: this.musicGain });
    }
    if (step % 16 === 0) {
      this._tone({ freq: chord[0], start: time, dur: 0.8, type: 'sine', gain: 0.05, dest: this.musicGain, attack: 0.2 });
    }
  }
}

export const audio = new AudioEngine();

