const KEY = 'tapeCrush.save.v1';

const DEFAULT_SAVE = {
  unlockedLevel: 1,
  stars: {},
  bestScore: {},
  musicMuted: false,
  sfxMuted: false
};

function load() {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return { ...DEFAULT_SAVE };
    const parsed = JSON.parse(raw);
    return { ...DEFAULT_SAVE, ...parsed };
  } catch (e) {
    return { ...DEFAULT_SAVE };
  }
}

function save(data) {
  try {
    localStorage.setItem(KEY, JSON.stringify(data));
  } catch (e) {
    // storage unavailable (private mode, quota) - fail silently, gameplay still works
  }
}

class SaveManagerImpl {
  constructor() {
    this.data = load();
  }

  get unlockedLevel() { return this.data.unlockedLevel; }

  unlockLevel(id) {
    if (id > this.data.unlockedLevel) {
      this.data.unlockedLevel = id;
      save(this.data);
    }
  }

  recordResult(levelId, stars, score) {
    const prevStars = this.data.stars[levelId] || 0;
    if (stars > prevStars) this.data.stars[levelId] = stars;
    const prevScore = this.data.bestScore[levelId] || 0;
    if (score > prevScore) this.data.bestScore[levelId] = score;
    save(this.data);
  }

  getStars(levelId) { return this.data.stars[levelId] || 0; }
  getBestScore(levelId) { return this.data.bestScore[levelId] || 0; }

  get musicMuted() { return this.data.musicMuted; }
  get sfxMuted() { return this.data.sfxMuted; }

  setMusicMuted(v) { this.data.musicMuted = v; save(this.data); }
  setSfxMuted(v) { this.data.sfxMuted = v; save(this.data); }

  totalStars() {
    return Object.values(this.data.stars).reduce((a, b) => a + b, 0);
  }
}

export const SaveManager = new SaveManagerImpl();

