import * as THREE from 'three';

const SHAPE_COLORS = [0xff5577, 0xff9a3c, 0xffd93c, 0x4ee08a, 0x3cb4ff, 0xb76bff];

export class Background3D {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(50, 1, 0.1, 100);
    this.camera.position.set(0, 0, 14);

    this._buildLights();
    this._buildCandies();

    this.targetColor = new THREE.Color(0x3a1266);
    this.scene.background = null;

    this.pointer = { x: 0, y: 0 };
    this.time = 0;
    this._running = true;
    this._raf = null;

    this._onPointerMove = (e) => {
      const x = (e.touches ? e.touches[0].clientX : e.clientX) / window.innerWidth;
      const y = (e.touches ? e.touches[0].clientY : e.clientY) / window.innerHeight;
      this.pointer.x = x * 2 - 1;
      this.pointer.y = -(y * 2 - 1);
    };
    window.addEventListener('pointermove', this._onPointerMove, { passive: true });

    this._onVisibility = () => {
      this._running = document.visibilityState === 'visible';
      if (this._running) this._loop();
    };
    document.addEventListener('visibilitychange', this._onVisibility);

    this.resize();
    window.addEventListener('resize', () => this.resize());
    this._loop();
  }

  _buildLights() {
    const ambient = new THREE.AmbientLight(0xffffff, 0.55);
    this.scene.add(ambient);
    const key = new THREE.DirectionalLight(0xffffff, 1.1);
    key.position.set(4, 6, 8);
    this.scene.add(key);
    const rim = new THREE.PointLight(0xff6ec7, 1.2, 40);
    rim.position.set(-6, -3, 6);
    this.scene.add(rim);
  }

  _buildCandies() {
    this.candies = [];
    const geoPool = [
      new THREE.IcosahedronGeometry(1, 0),
      new THREE.TorusGeometry(0.7, 0.28, 12, 24),
      new THREE.OctahedronGeometry(1, 0),
      new THREE.SphereGeometry(0.9, 16, 16),
      new THREE.DodecahedronGeometry(0.9, 0)
    ];

    const count = 16;
    for (let i = 0; i < count; i++) {
      const geo = geoPool[i % geoPool.length];
      const color = SHAPE_COLORS[i % SHAPE_COLORS.length];
      const mat = new THREE.MeshStandardMaterial({
        color,
        roughness: 0.28,
        metalness: 0.15,
        emissive: new THREE.Color(color).multiplyScalar(0.12)
      });
      const mesh = new THREE.Mesh(geo, mat);
      const radius = 9 + Math.random() * 7;
      const angle = Math.random() * Math.PI * 2;
      const depth = -6 - Math.random() * 10;
      mesh.position.set(Math.cos(angle) * radius, Math.sin(angle) * radius * 0.6, depth);
      const scale = 0.5 + Math.random() * 0.9;
      mesh.scale.setScalar(scale);
      mesh.userData = {
        spin: new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize().multiplyScalar(0.2 + Math.random() * 0.3),
        bobSpeed: 0.3 + Math.random() * 0.4,
        bobOffset: Math.random() * Math.PI * 2,
        baseY: mesh.position.y
      };
      this.scene.add(mesh);
      this.candies.push(mesh);
    }
  }

  setTheme(hex) {
    this.targetColor = new THREE.Color(hex).multiplyScalar(0.25).lerp(new THREE.Color(0x1a0638), 0.6);
  }

  resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }

  _loop = () => {
    if (!this._running) return;
    this._raf = requestAnimationFrame(this._loop);
    this.time += 0.016;

    for (const mesh of this.candies) {
      const u = mesh.userData;
      mesh.rotation.x += u.spin.x * 0.016;
      mesh.rotation.y += u.spin.y * 0.016;
      mesh.rotation.z += u.spin.z * 0.016;
      mesh.position.y = u.baseY + Math.sin(this.time * u.bobSpeed + u.bobOffset) * 0.6;
    }

    this.camera.position.x += (this.pointer.x * 1.5 - this.camera.position.x) * 0.02;
    this.camera.position.y += (this.pointer.y * 1.0 - this.camera.position.y) * 0.02;
    this.camera.lookAt(0, 0, -5);

    this.renderer.render(this.scene, this.camera);
  };

  dispose() {
    this._running = false;
    if (this._raf) cancelAnimationFrame(this._raf);
    window.removeEventListener('pointermove', this._onPointerMove);
    document.removeEventListener('visibilitychange', this._onVisibility);
    this.renderer.dispose();
  }
}

