const HEX_COLORS = [0xff5577, 0xff9a3c, 0xffd93c, 0x4ee08a, 0x3cb4ff, 0xb76bff];

export function colorHexFor(colorIndex) {
  return HEX_COLORS[colorIndex] ?? 0xffffff;
}

export function burst(scene, x, y, tint, { count = 12, texture = 'particle_glow', speed = 140, scaleStart = 0.7 } = {}) {
  const emitter = scene.add.particles(x, y, texture, {
    speed: { min: speed * 0.4, max: speed },
    scale: { start: scaleStart, end: 0 },
    alpha: { start: 1, end: 0 },
    lifespan: 420,
    tint,
    blendMode: 'ADD',
    emitting: false
  });
  emitter.setDepth(50);
  emitter.explode(count, 0, 0);
  scene.time.delayedCall(500, () => emitter.destroy());
  return emitter;
}

export function sparkleRing(scene, x, y, tint, count = 10) {
  const emitter = scene.add.particles(x, y, 'particle_spark', {
    speed: { min: 40, max: 90 },
    scale: { start: 0.5, end: 0 },
    alpha: { start: 1, end: 0 },
    lifespan: 600,
    rotate: { start: 0, end: 180 },
    tint,
    emitting: false
  });
  emitter.setDepth(51);
  emitter.explode(count, 0, 0);
  scene.time.delayedCall(700, () => emitter.destroy());
  return emitter;
}

