import { SPECIAL } from './constants.js';
import { textureKeyFor } from '../gfx/candyTextures.js';
import { burst, sparkleRing, colorHexFor } from '../gfx/particles.js';
import { audio } from '../audio/AudioEngine.js';

function tweenPromise(scene, config) {
  return new Promise((resolve) => {
    scene.tweens.add({ ...config, onComplete: resolve });
  });
}

export class BoardView {
  constructor(scene, board, { originX, originY, tileSize }) {
    this.scene = scene;
    this.board = board;
    this.originX = originX;
    this.originY = originY;
    this.tileSize = tileSize;
    this.cellSprite = Array.from({ length: board.rows }, () => new Array(board.cols).fill(null));
    this.container = scene.add.container(0, 0);
  }

  pixelFor(r, c) {
    return {
      x: this.originX + c * this.tileSize + this.tileSize / 2,
      y: this.originY + r * this.tileSize + this.tileSize / 2
    };
  }

  cellFromPixel(x, y) {
    const c = Math.floor((x - this.originX) / this.tileSize);
    const r = Math.floor((y - this.originY) / this.tileSize);
    if (r < 0 || r >= this.board.rows || c < 0 || c >= this.board.cols) return null;
    return { r, c };
  }

  renderInitial() {
    for (let r = 0; r < this.board.rows; r++) {
      for (let c = 0; c < this.board.cols; c++) {
        const tile = this.board.grid[r][c];
        const { x, y } = this.pixelFor(r, c);
        const sprite = this.scene.add.image(x, y - 420, textureKeyFor(tile.color, tile.special))
          .setDisplaySize(this.tileSize * 0.86, this.tileSize * 0.86);
        this.container.add(sprite);
        this.cellSprite[r][c] = sprite;
        this.scene.tweens.add({
          targets: sprite, y, duration: 420 + (r + c) * 18, ease: 'Bounce.Out', delay: (r + c) * 12
        });
      }
    }
  }

  setHighlight(r, c, on) {
    const sprite = this.cellSprite[r][c];
    if (!sprite) return;
    this.scene.tweens.killTweensOf(sprite);
    this.scene.tweens.add({
      targets: sprite, scale: on ? 1.16 : 1, duration: 140, ease: 'Sine.Out'
    });
  }

  pulseHint(r, c) {
    const sprite = this.cellSprite[r][c];
    if (!sprite) return null;
    const tween = this.scene.tweens.add({
      targets: sprite, scale: 1.12, duration: 420, yoyo: true, repeat: -1, ease: 'Sine.InOut'
    });
    return () => { tween.stop(); sprite.setScale(1); };
  }

  async playTurn(a, b, result) {
    const spriteA = this.cellSprite[a.r][a.c];
    const spriteB = this.cellSprite[b.r][b.c];
    const posA = this.pixelFor(a.r, a.c);
    const posB = this.pixelFor(b.r, b.c);

    audio.swap();
    await Promise.all([
      tweenPromise(this.scene, { targets: spriteA, x: posB.x, y: posB.y, duration: 160, ease: 'Sine.InOut' }),
      tweenPromise(this.scene, { targets: spriteB, x: posA.x, y: posA.y, duration: 160, ease: 'Sine.InOut' })
    ]);

    if (result.invalid) {
      audio.invalidSwap();
      this.scene.cameras.main.shake(120, 0.0025);
      await Promise.all([
        tweenPromise(this.scene, { targets: spriteA, x: posA.x, y: posA.y, duration: 160, ease: 'Sine.InOut' }),
        tweenPromise(this.scene, { targets: spriteB, x: posB.x, y: posB.y, duration: 160, ease: 'Sine.InOut' })
      ]);
      return;
    }

    this.cellSprite[a.r][a.c] = spriteB;
    this.cellSprite[b.r][b.c] = spriteA;

    for (const wave of result.waves) {
      await this._playWave(wave);
    }
  }

  async _playWave(wave) {
    const jobs = [];

    for (const spec of wave.specialsCreated) {
      const sprite = this.cellSprite[spec.r][spec.c];
      if (!sprite) continue;
      audio.specialCreate();
      jobs.push(tweenPromise(this.scene, {
        targets: sprite, scale: 1.35, duration: 160, yoyo: true, ease: 'Sine.Out',
        onYoyo: () => sprite.setTexture(textureKeyFor(spec.color, spec.type))
      }));
      sparkleRing(this.scene, sprite.x, sprite.y, colorHexFor(spec.color));
    }

    wave.cleared.forEach((cell, i) => {
      const sprite = this.cellSprite[cell.r][cell.c];
      if (!sprite) return;
      this.cellSprite[cell.r][cell.c] = null;
      const delay = Math.min(i * 14, 160);
      jobs.push(new Promise((resolve) => {
        this.scene.time.delayedCall(delay, () => {
          burst(this.scene, sprite.x, sprite.y, colorHexFor(cell.color), { count: cell.color < 0 ? 18 : 10 });
          this.scene.tweens.add({
            targets: sprite, scale: 0, alpha: 0, duration: 180, ease: 'Back.In',
            onComplete: () => { sprite.destroy(); resolve(); }
          });
        });
      }));
      audio.pop(wave.comboIndex);
    });

    for (const act of wave.activatedSpecials) {
      audio.specialActivate(act.special === SPECIAL.BOMB ? 'bomb' : act.special === SPECIAL.WRAPPED ? 'wrapped' : 'striped');
      const { x, y } = this.pixelFor(act.r, act.c);
      if (act.special === SPECIAL.STRIPED_ROW) this.scene.cameras.main.shake(90, 0.0015);
      if (act.special === SPECIAL.BOMB) this.scene.cameras.main.shake(180, 0.004);
      sparkleRing(this.scene, x, y, 0xffffff, 14);
    }

    await Promise.all(jobs);

    const fallJobs = [];
    for (const move of wave.fallMoves) {
      const sprite = this.cellSprite[move.fromRow][move.col];
      if (!sprite) continue;
      this.cellSprite[move.fromRow][move.col] = null;
      this.cellSprite[move.toRow][move.col] = sprite;
      const { y } = this.pixelFor(move.toRow, move.col);
      const dist = move.toRow - move.fromRow;
      fallJobs.push(tweenPromise(this.scene, {
        targets: sprite, y, duration: 140 + dist * 55, ease: 'Bounce.Out'
      }));
    }

    for (const spawn of wave.spawns) {
      const { x, y } = this.pixelFor(spawn.toRow, spawn.col);
      const sprite = this.scene.add.image(x, y - spawn.fromOffset * this.tileSize, textureKeyFor(spawn.color, SPECIAL.NONE))
        .setDisplaySize(this.tileSize * 0.86, this.tileSize * 0.86);
      this.container.add(sprite);
      this.cellSprite[spawn.toRow][spawn.col] = sprite;
      fallJobs.push(tweenPromise(this.scene, {
        targets: sprite, y, duration: 160 + spawn.fromOffset * 60, ease: 'Bounce.Out'
      }));
    }

    if (fallJobs.length) await Promise.all(fallJobs);
  }

  async playShuffle() {
    const sprites = [];
    for (let r = 0; r < this.board.rows; r++) {
      for (let c = 0; c < this.board.cols; c++) {
        if (this.cellSprite[r][c]) sprites.push(this.cellSprite[r][c]);
      }
    }
    await Promise.all(sprites.map((s) => tweenPromise(this.scene, { targets: s, alpha: 0, scale: 0.4, duration: 220, ease: 'Sine.In' })));
    sprites.forEach((s) => s.destroy());
    this.cellSprite = Array.from({ length: this.board.rows }, () => new Array(this.board.cols).fill(null));
    this.renderInitial();
  }
}

