import Phaser from 'phaser';
import { Match3Board } from '../game/Match3Board.js';
import { BoardView } from '../game/BoardView.js';
import { getLevel } from '../game/levels.js';
import { createPanel } from '../gfx/uiHelpers.js';
import { textureKeyFor } from '../gfx/candyTextures.js';
import { colorHexFor } from '../gfx/particles.js';
import { audio } from '../audio/AudioEngine.js';

const DIRS = [
  { dr: -1, dc: 0 }, { dr: 1, dc: 0 }, { dr: 0, dc: -1 }, { dr: 0, dc: 1 }
];

export class GameScene extends Phaser.Scene {
  constructor() {
    super('Game');
  }

  init(data) {
    this.levelId = data.levelId || 1;
  }

  create() {
    this.level = getLevel(this.levelId);
    this.board = new Match3Board(this.level.rows, this.level.cols, this.level.numColors);
    this.movesLeft = this.level.moves;
    this.score = 0;
    this.goalProgress = this.level.goals.map((g) => ({ ...g, done: 0 }));
    this.locked = false;
    this.selected = null;
    this.dragStart = null;
    this.dragFired = false;
    this.finished = false;

    if (this.game.bg3d) this.game.bg3d.setTheme(this.level.theme);

    this._buildLayout();
    this._buildHud();

    this.boardView.renderInitial();

    this.input.on('pointerdown', this._onPointerDown, this);
    this.input.on('pointermove', this._onPointerMove, this);
    this.input.on('pointerup', this._onPointerUp, this);

    this._resetHintTimer();

    this.events.once('shutdown', () => this._teardown());
  }

  _teardown() {
    if (this.hintTimer) this.hintTimer.remove();
    if (this.hintStop) this.hintStop();
    this.input.off('pointerdown', this._onPointerDown, this);
    this.input.off('pointermove', this._onPointerMove, this);
    this.input.off('pointerup', this._onPointerUp, this);
  }

  _buildLayout() {
    const { width, height } = this.scale;
    const topBar = 168;
    const bottomPad = 24;
    const sidePad = 16;

    const availW = width - sidePad * 2;
    const availH = height - topBar - bottomPad;
    const tileSize = Math.floor(Math.min(availW / this.level.cols, availH / this.level.rows, 92));

    const boardW = tileSize * this.level.cols;
    const boardH = tileSize * this.level.rows;
    const originX = (width - boardW) / 2;
    const originY = topBar + (availH - boardH) / 2;

    createPanel(this, {
      x: width / 2, y: originY + boardH / 2, width: boardW + 28, height: boardH + 28, color: 0x1c0a38, alpha: 0.55
    });

    this.boardView = new BoardView(this, this.board, { originX, originY, tileSize });
    this.topBarHeight = topBar;
  }

  _buildHud() {
    const { width } = this.scale;
    createPanel(this, { x: width / 2, y: 50, width: width - 16, height: 92, color: 0x241048, alpha: 0.85 });

    const pauseBtn = this.add.text(36, 50, '⏸', { fontSize: '34px', color: '#fff' }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    pauseBtn.on('pointerup', () => this._pause());

    this.scoreText = this.add.text(width - 36, 34, 'SCORE 0', {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '18px', fontStyle: '700', color: '#ffd93c'
    }).setOrigin(1, 0.5);

    this.movesText = this.add.text(width - 36, 62, `${this.movesLeft} moves`, {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '16px', color: '#ffffff'
    }).setOrigin(1, 0.5);

    this.goalIcons = [];
    const goalStartX = 90;
    this.goalProgress.forEach((goal, i) => {
      const x = goalStartX + i * 90;
      let icon;
      if (goal.type === 'collect') {
        icon = this.add.image(x, 50, textureKeyFor(goal.color, 'none')).setDisplaySize(40, 40);
      } else {
        icon = this.add.text(x, 50, '🏆', { fontSize: '30px' }).setOrigin(0.5);
      }
      const label = this.add.text(x, 76, this._goalLabel(goal), {
        fontFamily: 'Baloo 2, sans-serif', fontSize: '13px', color: '#fff'
      }).setOrigin(0.5);
      this.goalIcons.push({ goal, icon, label });
    });

    this.comboText = this.add.text(width / 2, this.topBarHeight / 2 + 10, '', {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '26px', fontStyle: '800', color: '#fff', stroke: '#5a1030', strokeThickness: 6
    }).setOrigin(0.5).setAlpha(0).setDepth(60);
  }

  _goalLabel(goal) {
    if (goal.type === 'score') return `${Math.min(goal.done, goal.amount)}/${goal.amount}`;
    return `${Math.min(goal.done, goal.amount)}/${goal.amount}`;
  }

  _updateHud() {
    this.scoreText.setText(`SCORE ${this.score}`);
    this.movesText.setText(`${Math.max(this.movesLeft, 0)} moves`);
    this.goalIcons.forEach(({ goal, label }) => label.setText(this._goalLabel(goal)));
  }

  _cellAtPointer(pointer) {
    return this.boardView.cellFromPixel(pointer.worldX, pointer.worldY);
  }

  _onPointerDown(pointer) {
    if (this.locked || this.finished) return;
    this._resetHintTimer();
    const cell = this._cellAtPointer(pointer);
    if (!cell) return;
    this.dragStart = cell;
    this.dragFired = false;
    this.dragOrigin = { x: pointer.x, y: pointer.y };
  }

  _onPointerMove(pointer) {
    if (this.locked || this.finished || !this.dragStart || this.dragFired) return;
    const dx = pointer.x - this.dragOrigin.x;
    const dy = pointer.y - this.dragOrigin.y;
    const threshold = this.boardView.tileSize * 0.32;
    if (Math.max(Math.abs(dx), Math.abs(dy)) < threshold) return;

    let dir;
    if (Math.abs(dx) > Math.abs(dy)) dir = dx > 0 ? DIRS[3] : DIRS[2];
    else dir = dy > 0 ? DIRS[1] : DIRS[0];

    const target = { r: this.dragStart.r + dir.dr, c: this.dragStart.c + dir.dc };
    this.dragFired = true;
    if (this.selected) { this.boardView.setHighlight(this.selected.r, this.selected.c, false); this.selected = null; }
    if (target.r >= 0 && target.r < this.level.rows && target.c >= 0 && target.c < this.level.cols) {
      this._attemptSwap(this.dragStart, target);
    }
  }

  _onPointerUp() {
    if (this.locked || this.finished) { this.dragStart = null; return; }
    if (!this.dragStart || this.dragFired) { this.dragStart = null; return; }

    const cell = this.dragStart;
    if (!this.selected) {
      this.selected = cell;
      this.boardView.setHighlight(cell.r, cell.c, true);
    } else if (this.selected.r === cell.r && this.selected.c === cell.c) {
      this.boardView.setHighlight(cell.r, cell.c, false);
      this.selected = null;
    } else if (this.board.isAdjacent(this.selected.r, this.selected.c, cell.r, cell.c)) {
      const a = this.selected;
      this.boardView.setHighlight(a.r, a.c, false);
      this.selected = null;
      this._attemptSwap(a, cell);
    } else {
      this.boardView.setHighlight(this.selected.r, this.selected.c, false);
      this.selected = cell;
      this.boardView.setHighlight(cell.r, cell.c, true);
    }
    this.dragStart = null;
  }

  async _attemptSwap(a, b) {
    this.locked = true;
    this._resetHintTimer();
    const result = this.board.trySwap(a.r, a.c, b.r, b.c);
    await this.boardView.playTurn(a, b, result);

    if (!result.invalid) {
      this.movesLeft--;
      this.score += result.scoreGained;
      this._applyCollected(result.collected);
      this._updateHud();
      this._showComboText(result.waves);

      if (!this.board.hasAvailableMoves()) {
        await this._showToast('No moves left — shuffling!');
        await this.boardView.playShuffle();
      }

      const won = this.goalProgress.every((g) => g.done >= g.amount);
      if (won) { this._finishLevel(true); this.locked = false; return; }
      if (this.movesLeft <= 0) { this._finishLevel(false); this.locked = false; return; }
    }

    this.locked = false;
    this._resetHintTimer();
  }

  _applyCollected(collected) {
    for (const goal of this.goalProgress) {
      if (goal.type === 'collect') {
        goal.done += collected[goal.color] || 0;
      } else if (goal.type === 'score') {
        goal.done = this.score;
      }
    }
  }

  _showComboText(waves) {
    const maxCombo = waves.reduce((m, w) => Math.max(m, w.comboIndex), 0);
    if (maxCombo < 2) return;
    const labels = ['', '', 'Sweet!', 'Tasty Combo!', 'Delicious!', 'AMAZING!', 'SUGAR RUSH!'];
    const text = labels[Math.min(maxCombo, labels.length - 1)] || 'INSANE!';
    this.comboText.setText(text).setAlpha(1).setScale(0.6);
    this.tweens.add({ targets: this.comboText, scale: 1.1, duration: 180, ease: 'Back.Out' });
    this.tweens.add({ targets: this.comboText, alpha: 0, delay: 500, duration: 300 });
  }

  _showToast(message) {
    const { width } = this.scale;
    const toast = this.add.text(width / 2, this.topBarHeight + 30, message, {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '18px', color: '#fff', backgroundColor: '#5a1030', padding: { x: 14, y: 8 }
    }).setOrigin(0.5).setAlpha(0).setDepth(70);
    return new Promise((resolve) => {
      this.tweens.add({
        targets: toast, alpha: 1, duration: 200, yoyo: true, hold: 700,
        onComplete: () => { toast.destroy(); resolve(); }
      });
    });
  }

  _resetHintTimer() {
    if (this.hintTimer) this.hintTimer.remove();
    if (this.hintStop) { this.hintStop(); this.hintStop = null; }
    this.hintTimer = this.time.addEvent({
      delay: 6500,
      callback: () => {
        if (this.locked || this.finished) return;
        const hint = this.board.getHint();
        if (!hint) return;
        this.hintStop = this.boardView.pulseHint(hint.ar, hint.ac);
        const stop2 = this.boardView.pulseHint(hint.br, hint.bc);
        const prevStop = this.hintStop;
        this.hintStop = () => { prevStop(); stop2(); };
      }
    });
  }

  _pause() {
    if (this.finished) return;
    audio.buttonClick();
    this.scene.launch('Pause', { levelId: this.levelId });
    this.scene.pause();
  }

  _finishLevel(won) {
    this.finished = true;
    if (this.hintTimer) this.hintTimer.remove();
    if (this.hintStop) this.hintStop();

    let stars = 0;
    if (won) {
      stars = this.level.starScores.filter((t) => this.score >= t).length;
      stars = Math.max(stars, 1);
      audio.levelWin();
    } else {
      audio.levelLose();
    }

    this.time.delayedCall(500, () => {
      this.scene.launch('Result', { won, stars, score: this.score, levelId: this.levelId });
      this.scene.pause();
    });
  }
}

