import Phaser from 'phaser';
import { createPanel, createButton, drawStars } from '../gfx/uiHelpers.js';
import { SaveManager } from '../game/SaveManager.js';
import { LEVELS } from '../game/levels.js';
import { burst } from '../gfx/particles.js';

export class ResultScene extends Phaser.Scene {
  constructor() {
    super('Result');
  }

  init(data) {
    this.won = data.won;
    this.stars = data.stars;
    this.score = data.score;
    this.levelId = data.levelId;
  }

  create() {
    const { width, height } = this.scale;
    this.add.rectangle(width / 2, height / 2, width, height, 0x000000, 0.6).setInteractive();

    if (this.won) {
      SaveManager.recordResult(this.levelId, this.stars, this.score);
      SaveManager.unlockLevel(this.levelId + 1);
    }

    createPanel(this, { x: width / 2, y: height / 2, width: Math.min(width * 0.85, 380), height: 420, color: 0x241048, alpha: 0.97 });

    this.add.text(width / 2, height / 2 - 168, this.won ? 'LEVEL COMPLETE!' : 'OUT OF MOVES', {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '26px', fontStyle: '800', color: this.won ? '#4ee08a' : '#ff5577'
    }).setOrigin(0.5);

    if (this.won) {
      const starsContainer = drawStars(this, width / 2, height / 2 - 108, 3, 34, 0);
      this.time.delayedCall(200, () => this._popStars(starsContainer));
      this._confetti(width, height);
    } else {
      this.add.text(width / 2, height / 2 - 100, '😿', { fontSize: '54px' }).setOrigin(0.5);
    }

    this.add.text(width / 2, height / 2 - 40, `Score: ${this.score}`, {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '20px', color: '#fff'
    }).setOrigin(0.5);

    const hasNext = LEVELS.some((l) => l.id === this.levelId + 1);

    let y = height / 2 + 10;
    if (this.won && hasNext) {
      createButton(this, {
        x: width / 2, y, width: 240, height: 58, label: 'NEXT LEVEL', color: 0x4ee08a,
        onClick: () => this._goto('Game', { levelId: this.levelId + 1 })
      });
      y += 72;
    }

    createButton(this, {
      x: width / 2, y, width: 240, height: 58, label: this.won ? 'Replay' : 'Retry', color: 0xff9a3c,
      onClick: () => this._goto('Game', { levelId: this.levelId })
    });
    y += 72;

    createButton(this, {
      x: width / 2, y, width: 240, height: 54, label: 'Level Map', color: 0x3cb4ff,
      onClick: () => this._goto('LevelSelect')
    });
  }

  _goto(key, data) {
    this.scene.stop('Game');
    this.scene.stop();
    this.scene.start(key, data);
  }

  _popStars(container) {
    const stars = container.list;
    stars.forEach((star, i) => {
      this.time.delayedCall(i * 260, () => {
        if (i < this.stars) {
          star.setFillStyle(0xffd93c).setStrokeStyle(2, 0xc99a00);
          this.tweens.add({ targets: star, scale: 1.6, duration: 160, yoyo: true, ease: 'Back.Out' });
          import('../audio/AudioEngine.js').then(({ audio }) => audio.star());
        }
      });
    });
  }

  _confetti(width, height) {
    const colors = [0xff5577, 0xff9a3c, 0xffd93c, 0x4ee08a, 0x3cb4ff, 0xb76bff];
    for (let i = 0; i < 3; i++) {
      this.time.delayedCall(i * 150, () => {
        burst(this, width * (0.25 + i * 0.25), height * 0.25, Phaser.Utils.Array.GetRandom(colors), { count: 20, speed: 260, scaleStart: 1 });
      });
    }
  }
}

