import Phaser from 'phaser';
import { generateCandyTextures } from '../gfx/candyTextures.js';

const TIPS = [
  'warming up the sugar engine…',
  'lining up the candies…',
  'polishing the gems…',
  'tuning the chime synthesizer…',
  'rolling out the caramel…'
];

export class PreloadScene extends Phaser.Scene {
  constructor() {
    super('Preload');
  }

  create() {
    const fill = document.getElementById('loading-bar-fill');
    const tip = document.getElementById('loading-tip');
    const screen = document.getElementById('loading-screen');
    if (tip) tip.textContent = Phaser.Utils.Array.GetRandom(TIPS);
    if (fill) fill.style.width = '15%';

    generateCandyTextures(this, 128);

    if (fill) fill.style.width = '100%';

    this.time.delayedCall(260, () => {
      if (screen) screen.classList.add('hidden');
      this.scene.start('Menu');
    });
  }
}

