import { Match3Board } from '/Users/oyabun/Downloads/tape-crush/src/game/Match3Board.js';
import { SPECIAL } from '/Users/oyabun/Downloads/tape-crush/src/game/constants.js';

function printGrid(board) {
  for (let r = 0; r < board.rows; r++) {
    console.log(board.grid[r].map(t => t ? `${t.color}${t.special!=='none'?'*':' '}` : '. ').join(' '));
  }
}

// Run many random games to shake out exceptions / invariant violations
let totalSwaps = 0, totalInvalid = 0, totalValid = 0, maxCombo = 0;
for (let game = 0; game < 50; game++) {
  const board = new Match3Board(8, 8, 6);
  for (let i = 0; i < 300; i++) {
    const r = Math.floor(Math.random() * board.rows);
    const c = Math.floor(Math.random() * board.cols);
    const dirs = [[0,1],[1,0]];
    const [dr,dc] = dirs[Math.floor(Math.random()*dirs.length)];
    const r2 = r+dr, c2 = c+dc;
    if (r2 >= board.rows || c2 >= board.cols) continue;
    totalSwaps++;
    const res = board.trySwap(r,c,r2,c2);
    if (res.invalid) { totalInvalid++; continue; }
    totalValid++;
    for (const w of res.waves) maxCombo = Math.max(maxCombo, w.comboIndex);

    // invariants: grid fully populated, no nulls, ids unique, colors in range
    const ids = new Set();
    for (let rr = 0; rr < board.rows; rr++) {
      for (let cc = 0; cc < board.cols; cc++) {
        const t = board.grid[rr][cc];
        if (!t) throw new Error(`null tile at ${rr},${cc} game ${game} i ${i}`);
        if (ids.has(t.id)) throw new Error(`duplicate id ${t.id}`);
        ids.add(t.id);
        if (t.color < 0 || t.color > 5) throw new Error(`bad color ${t.color}`);
      }
    }
    if (!board.hasAvailableMoves()) {
      board.shuffleBoard();
      if (!board.hasAvailableMoves()) throw new Error('shuffle failed to produce moves');
    }
  }
}
console.log({totalSwaps, totalInvalid, totalValid, maxCombo});
console.log('OK - no exceptions, all invariants held');
