cat > /tmp/claude-1000/-Users-oyabun-Downloads-tape-crush/a769e2a7-763d-445c-99c2-7527923333b2/scratchpad/test_specials.mjs << 'EOF'
import { Match3Board } from '/Users/oyabun/Downloads/tape-crush/src/game/Match3Board.js';
import { SPECIAL } from '/Users/oyabun/Downloads/tape-crush/src/game/constants.js';

function freshBoard(rows=8, cols=8, colors=6) {
  const b = new Match3Board(rows, cols, colors);
  return b;
}

function setCell(b, r, c, color, special=SPECIAL.NONE) {
  b.grid[r][c] = { id: 9000 + r*100+c, color, special };
}

function fillNeutral(b, excludeColor) {
  // fill whole board with a color guaranteed not to cause matches, skip if would collide
  for (let r=0;r<b.rows;r++) for (let c=0;c<b.cols;c++) {
    if (!b.grid[r][c]) setCell(b, r, c, (excludeColor+3)%6);
  }
}

// TEST 1: horizontal 4-match creates STRIPED_ROW at swap cell
{
  const b = freshBoard();
  fillNeutral(b, 0);
  // row 3: cols 0-3 will be color0 except col2 which starts as color1 (swapped in from col2,row4)
  setCell(b,3,0,0); setCell(b,3,1,0); setCell(b,3,2,1); setCell(b,3,3,0);
  setCell(b,4,2,0); // swap (3,2)<->(4,2) => row3 becomes 0,0,0,0 at cols0-3
  const res = b.trySwap(3,2,4,2);
  console.log('TEST1 invalid?', res.invalid);
  const spawned = res.waves.flatMap(w=>w.specialsCreated);
  console.log('TEST1 specials created:', spawned);
  console.log('TEST1 tile at swap cell (3,2):', b.grid[3][2]);
  if (res.invalid) throw new Error('T1 should be valid');
  if (b.grid[3][2].special !== SPECIAL.STRIPED_ROW) throw new Error('T1 expected STRIPED_ROW at swap cell, got '+b.grid[3][2].special);
}

// TEST 2: 5-match creates BOMB
{
  const b = freshBoard();
  fillNeutral(b, 0);
  setCell(b,2,0,0); setCell(b,2,1,0); setCell(b,2,2,0); setCell(b,2,3,0);
