    const { width, height } = this.scale;
    this.cameras.main.setBackgroundColor('rgba(0,0,0,0)');

    const title = this.add.text(width / 2, height * 0.26, 'TAPE CRUSH', {
      fontFamily: 'Baloo 2, sans-serif',
      fontSize: `${Math.min(width * 0.12, 76)}px`,
      fontStyle: '800',
      color: '#ffffff',
      stroke: '#7b1050',
      strokeThickness: 10
    }).setOrigin(0.5).setScale(0.6).setAlpha(0);

    this.tweens.add({
      targets: title, scale: 1, alpha: 1, duration: 650, ease: 'Back.Out',
      onComplete: () => {
        this.tweens.add({ targets: title, y: title.y - 8, duration: 1400, yoyo: true, repeat: -1, ease: 'Sine.InOut' });
      }
    });

    this.add.text(width / 2, height * 0.26 + 58, 'an original sugar-rush match-3', {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '18px', color: '#e6d6ff'
    }).setOrigin(0.5);

    const stars = SaveManager.totalStars();
    this.add.text(width / 2, height * 0.26 + 90, `★ ${stars} stars collected`, {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '16px', color: '#ffd93c'
    }).setOrigin(0.5);

    const playLabel = SaveManager.unlockedLevel > 1 ? 'CONTINUE' : 'PLAY';
    createButton(this, {
      x: width / 2, y: height * 0.52, width: Math.min(width * 0.6, 280), height: 72,
      label: playLabel, color: 0xff5577, fontSize: 30,
      onClick: () => this.scene.start('LevelSelect')
    });

    createButton(this, {
      x: width / 2, y: height * 0.52 + 92, width: Math.min(width * 0.6, 280), height: 56,
      label: 'LEVELS', color: 0x3cb4ff, fontSize: 24,
      onClick: () => this.scene.start('LevelSelect')
    });

    this._buildSoundToggle(width, height);

    this.add.text(width / 2, height - 24, 'made with Phaser 3 · three.js · Web Audio', {
      fontFamily: 'Baloo 2, sans-serif', fontSize: '12px', color: 'rgba(255,255,255,0.4)'
    }).setOrigin(0.5);
  }

  _buildSoundToggle(width) {
    const makeToggle = (x, y, label, getMuted, setMuted) => {
      const draw = (btn, muted) => {
        btn.txt.setText(muted ? `${label} OFF` : `${label} ON`);
        btn.bg.clear();
        btn.bg.fillStyle(muted ? 0x55406e : 0x3cb4ff, 1);
        btn.bg.fillRoundedRect(-70, -22, 140, 44, 14);
      };
      const bg = this.add.graphics();
      const txt = this.add.text(0, 0, '', { fontFamily: 'Baloo 2, sans-serif', fontSize: '16px', color: '#fff' }).setOrigin(0.5);
      const container = this.add.container(x, y, [bg, txt]);
      container.setSize(140, 44);
      container.setInteractive({ useHandCursor: true });
      const btn = { bg, txt };
      draw(btn, getMuted());
      container.on('pointerup', () => {
        const muted = !getMuted();
        setMuted(muted);
        draw(btn, muted);
        audio.buttonClick();
      });
      return container;
    };

    makeToggle(width / 2 - 78, 48, '🎵', () => SaveManager.musicMuted, (v) => { SaveManager.setMusicMuted(v); audio.setMusicMuted(v); });
    makeToggle(width / 2 + 78, 48, '🔊', () => SaveManager.sfxMuted, (v) => { SaveManager.setSfxMuted(v); audio.setSfxMuted(v); });
  }
}

