import Phaser from 'phaser';
import { audio } from '../audio/AudioEngine.js';

function shade(hex, factor) {
  const c = Phaser.Display.Color.ValueToColor(hex);
  const r = Phaser.Math.Clamp(Math.round(c.red * factor), 0, 255);
  const g = Phaser.Math.Clamp(Math.round(c.green * factor), 0, 255);
  const b = Phaser.Math.Clamp(Math.round(c.blue * factor), 0, 255);
  return Phaser.Display.Color.GetColor(r, g, b);
}

export function createButton(scene, { x, y, width = 220, height = 64, label, color = 0xff5577, fontSize = 28, onClick, icon = null }) {
  const container = scene.add.container(x, y);
  const radius = height * 0.3;

  const shadow = scene.add.graphics();
  shadow.fillStyle(0x000000, 0.35);
  shadow.fillRoundedRect(-width / 2, -height / 2 + 6, width, height, radius);

  const base = scene.add.graphics();
  const top = shade(color, 1.0);
  const bottom = shade(color, 0.72);
  base.fillStyle(bottom, 1);
  base.fillRoundedRect(-width / 2, -height / 2, width, height, radius);
  base.fillStyle(top, 1);
  base.fillRoundedRect(-width / 2, -height / 2, width, height * 0.62, { tl: radius, tr: radius, bl: 0, br: 0 });

  const gloss = scene.add.graphics();
  gloss.fillStyle(0xffffff, 0.22);
  gloss.fillRoundedRect(-width / 2 + 6, -height / 2 + 5, width - 12, height * 0.32, radius * 0.7);

  const border = scene.add.graphics();
  border.lineStyle(3, shade(color, 0.5), 1);
  border.strokeRoundedRect(-width / 2, -height / 2, width, height, radius);

  const text = scene.add.text(icon ? 10 : 0, -1, label, {
    fontFamily: '"Baloo 2", sans-serif',
    fontSize: `${fontSize}px`,
    fontStyle: '700',
    color: '#ffffff',
    stroke: shade(color, 0.45) === undefined ? '#000' : '#5a1030',
    strokeThickness: 4
  }).setOrigin(0.5);

  container.add([shadow, base, gloss, border, text]);

  if (icon) {
    const iconText = scene.add.text(-width / 2 + 34, 0, icon, { fontSize: `${fontSize + 6}px` }).setOrigin(0.5);
    container.add(iconText);
  }

  container.setSize(width, height);
  container.setInteractive({ useHandCursor: true });

  container.on('pointerover', () => {
    scene.tweens.add({ targets: container, scale: 1.04, duration: 120, ease: 'Sine.Out' });
  });
  container.on('pointerout', () => {
    scene.tweens.add({ targets: container, scale: 1, y, x, duration: 120, ease: 'Sine.Out' });
  });
  container.on('pointerdown', () => {
    scene.tweens.add({ targets: container, scale: 0.94, y: y + 4, duration: 70, ease: 'Sine.Out' });
  });
  container.on('pointerup', () => {
    scene.tweens.add({
      targets: container, scale: 1, y, duration: 110, ease: 'Back.Out',
      onComplete: () => {
        audio.buttonClick();
        if (onClick) onClick();
      }
    });
  });

  return container;
}

export function createPanel(scene, { x, y, width, height, color = 0x2d0f55, radius = 24, alpha = 0.92 }) {
  const g = scene.add.graphics();
  g.setPosition(x, y);
  g.fillStyle(0x000000, 0.25);
  g.fillRoundedRect(-width / 2 + 4, -height / 2 + 8, width, height, radius);
  g.fillStyle(color, alpha);
  g.fillRoundedRect(-width / 2, -height / 2, width, height, radius);
  g.lineStyle(3, 0xffffff, 0.12);
  g.strokeRoundedRect(-width / 2, -height / 2, width, height, radius);
  return g;
}

export function drawStars(scene, x, y, count, size = 22, earned = 0) {
  const container = scene.add.container(x, y);
  const spacing = size * 1.3;
  for (let i = 0; i < count; i++) {
    const sx = (i - (count - 1) / 2) * spacing;
    const filled = i < earned;
    const star = scene.add.star(sx, 0, 5, size * 0.42, size, filled ? 0xffd93c : 0x4a3570)
      .setStrokeStyle(2, filled ? 0xc99a00 : 0x2a1a4a);
    container.add(star);
  }
  return container;
}

