import Phaser from 'phaser';
import './style.css';
import { Background3D } from './gfx/Background3D.js';
import { BootScene } from './scenes/BootScene.js';
import { PreloadScene } from './scenes/PreloadScene.js';
import { MenuScene } from './scenes/MenuScene.js';
import { LevelSelectScene } from './scenes/LevelSelectScene.js';
import { GameScene } from './scenes/GameScene.js';
import { PauseScene } from './scenes/PauseScene.js';
import { ResultScene } from './scenes/ResultScene.js';
import { audio } from './audio/AudioEngine.js';
import { SaveManager } from './game/SaveManager.js';

const bg3d = new Background3D(document.getElementById('bg3d'));

const config = {
  type: Phaser.AUTO,
  parent: 'game-root',
  backgroundColor: 'rgba(0,0,0,0)',
  transparent: true,
  scale: {
    mode: Phaser.Scale.RESIZE,
    autoCenter: Phaser.Scale.CENTER_BOTH
  },
  scene: [BootScene, PreloadScene, MenuScene, LevelSelectScene, GameScene, PauseScene, ResultScene],
  render: { antialias: true, roundPixels: false }
};

const game = new Phaser.Game(config);
game.bg3d = bg3d;
window.__tapeCrush = game;

audio.setMusicMuted(SaveManager.musicMuted);
audio.setSfxMuted(SaveManager.sfxMuted);

function unlockAudio() {
  audio.init();
  audio.resume();
  if (!SaveManager.musicMuted) audio.startMusic();
  window.removeEventListener('pointerdown', unlockAudio);
  window.removeEventListener('touchstart', unlockAudio);
  window.removeEventListener('keydown', unlockAudio);
}
window.addEventListener('pointerdown', unlockAudio);
window.addEventListener('touchstart', unlockAudio);
window.addEventListener('keydown', unlockAudio);

window.addEventListener('beforeunload', () => {
  bg3d.dispose();
});

